internal class GUPPriceEngineMarginCodeLine extends GUPPriceEngineAbstractLine
{
    GUPPriceMarginComponentSetup marginComponentSetup;
    GUPMarginComponentPriceAdjustment marginComponentHeader;
    GUPMarginComponentPriceAdjustmentLine marginComponentLine;

    // UnitOfMeasure.Symbol.
    str unitSymbol;

}

Method.Source:
    public void new(GUPPriceMarginComponentSetup _marginComponentSetup,
        GUPMarginComponentPriceAdjustment _marginComponentHeader, 
        GUPMarginComponentPriceAdjustmentLine _marginComponentLine, 
        GUPPriceEngineAttributeGroupObject _headerAttributeGroup,
        GUPPriceEngineAttributeGroupObject _lineAttributeGroup,
        UnitOfMeasure unitOfMeasure)
    {
        // Make a copy by the cursor.
        this.marginComponentSetup = _marginComponentSetup;
        this.marginComponentHeader = _marginComponentHeader;
        this.marginComponentLine = _marginComponentLine;
        
        if (unitOfMeasure)
        {
            this.unitSymbol = unitOfMeasure.Symbol;
        }

        super(_headerAttributeGroup, _lineAttributeGroup);
    }
